import java.io.*;

public class Main {
    static final byte[] buf = new byte[1 << 16];
    static int bufLen = 0, bufPos = 0;

    static int readByte() throws IOException {
        if (bufPos == bufLen) {
            bufLen = System.in.read(buf, 0, buf.length);
            bufPos = 0;
            if (bufLen <= 0) return -1;
        }
        return buf[bufPos++];
    }

    static int readInt() throws IOException {
        int c = readByte();
        while (c != -1 && (c < '0' || c > '9')) c = readByte();
        int x = 0;
        while (c >= '0' && c <= '9') {
            x = x * 10 + (c - '0');
            c = readByte();
        }
        return x;
    }

    public static void main(String[] args) throws IOException {
        int n = readInt();
        int[] h = new int[n];
        for (int i = 0; i < n; i++) h[i] = readInt();
        // left[i]: nearest index to the left with a strictly lower building (monotonic stack).
        int[] left = new int[n], st = new int[n];
        int top = 0;
        for (int i = 0; i < n; i++) {
            while (top > 0 && h[st[top - 1]] >= h[i]) top--;
            left[i] = top == 0 ? -1 : st[top - 1];
            st[top++] = i;
        }
        top = 0;
        long best = 0;
        for (int i = n - 1; i >= 0; i--) {
            while (top > 0 && h[st[top - 1]] >= h[i]) top--;
            int right = top == 0 ? n : st[top - 1];
            st[top++] = i;
            // Building i is the lowest on (left, right): the square side is limited by both.
            best = Math.max(best, Math.min(h[i], right - left[i] - 1));
        }
        System.out.println(best * best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<16)
	readInt := func() int {
		c, err := reader.ReadByte()
		for err == nil && (c < '0' || c > '9') {
			c, err = reader.ReadByte()
		}
		x := 0
		for err == nil && c >= '0' && c <= '9' {
			x = x*10 + int(c-'0')
			c, err = reader.ReadByte()
		}
		return x
	}
	n := readInt()
	h := make([]int32, n)
	for i := range h {
		h[i] = int32(readInt())
	}
	// left[i]: nearest index to the left with a strictly lower building (monotonic stack).
	left := make([]int32, n)
	st := make([]int32, 0, n)
	for i := 0; i < n; i++ {
		for len(st) > 0 && h[st[len(st)-1]] >= h[i] {
			st = st[:len(st)-1]
		}
		if len(st) == 0 {
			left[i] = -1
		} else {
			left[i] = st[len(st)-1]
		}
		st = append(st, int32(i))
	}
	st = st[:0]
	var best int64
	for i := n - 1; i >= 0; i-- {
		for len(st) > 0 && h[st[len(st)-1]] >= h[i] {
			st = st[:len(st)-1]
		}
		right := int32(n)
		if len(st) > 0 {
			right = st[len(st)-1]
		}
		st = append(st, int32(i))
		// Building i is the lowest on (left, right): the square side is limited by both.
		best = max(best, min(int64(h[i]), int64(right-left[i]-1)))
	}
	fmt.Println(best * best)
}
